def max_product_of_digits(n):
    s = str(n)
    max_product = 1

    # Try all numbers with one fewer digit (all 9s)
    for i in range(len(s) - 1):
        candidate = '9' * i + '9' * (len(s) - i - 1)
        product = 1
        for ch in candidate:
            product *= int(ch)
        max_product = max(max_product, product)

    # Try decreasing each digit and setting rest to 9
    for i in range(len(s)):
        # Try decreasing the digit
        if i == 0:
            # First digit can't be 0
            if s[i] > '1':
                candidate = str(int(s[i]) - 1) + '9' * (len(s) - i - 1)
                product = 1
                for ch in candidate:
                    product *= int(ch)
                max_product = max(max_product, product)
        else:
            # Other digits can be 0
            if s[i] > '0':
                candidate = s[:i] + str(int(s[i]) - 1) + '9' * (len(s) - i - 1)
                product = 1
                for ch in candidate:
                    product *= int(ch)
                max_product = max(max_product, product)

    return max_product

n = int(input())
print(max_product_of_digits(n))
"}

