from collections import Counter

t = input().strip()
pieces = input().strip()

# Count frequency of each digit in pieces
digit_count = Counter(pieces)

# Group digits by their mimic groups
mimic_groups = {
    '2': ['2', '5'],
    '5': ['2', '5'],
    '6': ['6', '9'],
    '9': ['6', '9'],
    '0': ['0'],
    '1': ['1'],
    '3': ['3'],
    '4': ['4'],
    '7': ['7'],
    '8': ['8']
}

# Count how many of each mimic group we need in t
t_needed = {}
for digit in t:
    for group, members in mimic_groups.items():
        if digit in members:
            t_needed[group] = t_needed.get(group, 0) + 1
            break

# Count how many of each mimic group we have
available = {}
for digit, count in digit_count.items():
    for group, members in mimic_groups.items():
        if digit in members:
            available[group] = available.get(group, 0) + count
            break

# Calculate how many instances we can make
result = float('inf')
for group, needed in t_needed.items():
    if group in available:
        result = min(result, available[group] // needed)
    else:
        # We don't have this group at all
        result = 0
        break

print(result)
"}

