# Read input
s = input().strip()

# Identify which colors are present
present = set()
for c in s:
    if c in 'RGBY':
        present.add(c)

# Find the position of each color
positions = {}
for i, c in enumerate(s):
    if c in 'RGBY':
        positions[c] = i

# Determine the cyclic pattern
# The pattern is a cyclic permutation of the present colors
# Let's find the order by looking at the relative positions
order = list(present)

# Check if the pattern is consistent with the positions
# The first occurrence of each color should follow the pattern
for i in range(len(order)):
    expected_color = order[i % len(order)]
    if s[positions[expected_color]] != expected_color:
        # If not consistent, try a different order
        # Try all permutations of the present colors
        from itertools import permutations
        for perm in permutations(order):
            consistent = True
            for i in range(len(perm)):
                expected_color = perm[i % len(perm)]
                if s[positions[expected_color]] != expected_color:
                    consistent = False
                    break
            if consistent:
                order = perm
                break
        break

# Now count dead bulbs for each color
dead = {'R': 0, 'B': 0, 'Y': 0, 'G': 0}
for i, c in enumerate(s):
    if c == '!':
        # Determine which color should be here based on the pattern
        expected_color = order[i % len(order)]
        dead[expected_color] += 1

# Output the result
print(dead['R'], dead['B'], dead['Y'], dead['G'])
"}

