def is_subsequence(s, t):
    it = iter(s)
    return all(c in it for c in t)

def solve():
    s = input().strip()
    t = input().strip()

    # Check if t is a subsequence of s
    if not is_subsequence(s, t):
        print("No")
        return

    # Find the farthest position where we can match prefix of t
    prefix = [0] * len(s)
    j = 0
    for i in range(len(s)):
        if j < len(t) and s[i] == t[j]:
            prefix[i] = j + 1  # 1-indexed
            j += 1

    # Find the farthest position where we can match suffix of t
    suffix = [0] * len(s)
    j = len(t) - 1
    for i in range(len(s) - 1, -1, -1):
        if j >= 0 and s[i] == t[j]:
            suffix[i] = j + 1  # 1-indexed
            j -= 1

    # Check if every character can be part of some subsequence
    for i in range(len(s)):
        # If we can match prefix up to some position j, and suffix from position j+1
        # Then character at position i can be part of a subsequence
        if prefix[i] > 0 and suffix[i] < len(t):
            print("Yes")
            return

    print("No")

