import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    edges = []

    for _ in range(m):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        edges.append((u, v))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append((v, edges.index((u, v))))  # Store edge index

    # Check if the graph has a cycle
    in_degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v, _ in adj[u]:
            in_degree[v] += 1

    queue = []
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    topo_order = []
    while queue:
        u = queue.pop(0)
        topo_order.append(u)
        for v, _ in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Actually, we don't need topo_order
    # We just need to know if there's a cycle
    has_cycle = len(topo_order) != n

    # If there's no cycle, we can color everything with 1
    if not has_cycle:
        k = 1
        colors = [1] * m
    else:
        # If there is a cycle, we need 2 colors
        k = 2
        colors = [1] * m

        # Color edges differently based on vertex indices
        for edge_idx, (u, v) in enumerate(edges):
            if u < v:
                colors[edge_idx] = 1
            else:
                colors[edge_idx] = 2

    print(k)
    print(' '.join(map(str, colors)))

if __name__ == "__main__":
    solve()
