import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    b = list(map(int, data[n+1:2*n+1]))
    m = int(data[2*n+1])

    # Precompute prefix maximums
    max_a = [0] * n
    max_b = [0] * n

    max_a[0] = a[0]
    max_b[0] = b[0]

    for i in range(1, n):
        max_a[i] = max(max_a[i-1], a[i])
        max_b[i] = max(max_b[i-1], b[i])

    # DP: dp[i][j] = number of ways to interleave first i points of a and first j points of b
    # with non-decreasing x-coordinates
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(n + 1):
        for j in range(n + 1):
            if dp[i][j] == 0:
                continue

            # Try adding a[i] (if i < n)
            if i < n:
                # Previous max
                if i == 0:
                    prev_max = 0
                elif j == 0:
                    prev_max = max_a[i-1]
                else:
                    prev_max = max(max_a[i-1], max_b[j-1])

                # New max
                if prev_max <= a[i]:
                    dp[i+1][j] = (dp[i+1][j] + dp[i][j]) % m

            # Try adding b[j] (if j < n)
            if j < n:
                # Previous max
                if j == 0:
                    prev_max = 0
                elif i == 0:
                    prev_max = max_b[j-1]
                else:
                    prev_max = max(max_a[i-1], max_b[j-1])

                # New max
                if prev_max <= b[j]:
                    dp[i][j+1] = (dp[i][j+1] + dp[i][j]) % m

    print(dp[n][n] % m)

if __name__ == "__main__":
    solve()
"}

