import sys

def solve():
    MOD = 10**9 + 7
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    x = list(map(int, data[1:1+n]))

    x.sort()

    power = pow(2, n-2, MOD)
    result = 0
    for i in range(n):
        for j in range(i+1, n):
            diff = (x[j] - x[i]) % MOD
            result = (result + diff * power) % MOD

    print(result)

if __name__ == "__main__":
    solve()
