        """Trace steps from a node in a graph"""
        current = start
        for _ in range(steps):
            if not graph[current]:
                # No outgoing edges
                return None
            current = graph[current][0]
        return current

    def reverse_trace_steps(start, steps, reverse_graph):
        """Trace steps in reverse graph"""
        current = start
        for _ in range(steps):
            if not reverse_graph[current]:
                # No incoming edges
                return None
            current = reverse_graph[current][0]
        return current

    # Try values of t from 1 to n*n (some upper bound)
    for t in range(1, n * n + 1):
