            for part in parts[1:]:
                dependencies[part - 1].append(i)

    # Try all possible completion orders using DFS
    # We'll use a recursive approach to try all topological orders

    # Memoization cache
    memo = {}

    def dfs(visited, curr_time, curr_computer, path):
