def parse_grid(lines):
    """Parse the 9x9 grid from the input lines."""
    grid = []
    for i in range(9):
        row = []
        for j in range(3):
            # Get the 3x3 small field at position (i // 3, i % 3)
            field = ''
            for k in range(3):
                # Get the line for the k-th row of this small field
                line_index = k * 9 + (i // 3) * 3 + j
                if line_index < len(lines):
                    field += lines[line_index].strip()
            grid.append(field)
    return grid

def find_last_move_field(lines):
    """Find the small field where the last move was made."""
    # The last move coordinates are on line 20
    last_line = lines[20].strip().split()
    x, y = int(last_line[0]), int(last_line[1])

    # Convert to 0-indexed coordinates
    x -= 1
    y -= 1

    # Find which small field (i, j) contains this cell
    small_i = (y - 1) // 3
    small_j = (x - 1) // 3

    return small_i, small_j

def solve():
