import sys
from collections import defaultdict

def solve():
    MOD = 10**9 + 7
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Build graph
    edges = defaultdict(set)
    self_loops = []

    for i in range(n):
        k = int(next(it))
        coords = list(map(int, [next(it) for _ in range(k)]))

        if k == 1:
            # self-loop
            self_loops.append((i, coords[0]))
        else:
            # edge
            a, b = coords
            if a > b:
                a, b = b, a
            edges[(a, b)].add(i)

    # Union-Find to find connected components
    parent = {}
    def find(x):
        if x not in parent:
            parent[x] = x
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px = find(x)
        py = find(y)
        if px != py:
            parent[py] = px

    # Process edges to connect components
    for (a, b), indices in edges.items():
        for idx in indices:
            union(a, b)

    # Find all components
    components = defaultdict(list)
    for pos in range(1, m + 1):
        if pos in parent:
            root = find(pos)
            components[root].append(pos)

    # Collect all vectors in S'
    s_prime = []

    # Process self-loops
    for idx, pos in self_loops:
        root = find(pos)
        components[root].append((idx, 'self', pos))

    # Process edges
    for (a, b), indices in edges.items():
        for idx in indices:
            root = find(a)
            components[root].append((idx, 'edge', (a, b)))

    # Now, for each component, we need:
    # - One self-loop (if any) with the smallest index in that component
    # - One edge per distinct pair in that component with the smallest indices

    # Sort self-loops in each component by index
    for root, vecs in components.items():
        self_loop_indices = [v for v in vecs if v[1] == 'self']
        if self_loop_indices:
            # Pick the one with the smallest index
            chosen_idx = min(self_loop_indices, key=lambda x: x[0])[0]
            s_prime.append(chosen_idx)
            # Remove it from the list to avoid re-picking
            for v in vecs:
                if v[0] == chosen_idx:
                    vecs.remove(v)
                    break

    # For edges, we need one per distinct pair. Since we sorted by index,
    # we just pick all of them
    for root, vecs in components.items():
        edge_indices = [v for v in vecs if v[1] == 'edge']
        if edge_indices:
            s_prime.extend([v[0] for v in edge_indices])

    # Sort the final result
    s_prime.sort()

    d = len(s_prime)
    result = (pow(2, d, MOD), d)

    print(result[0], result[1])
    print(' '.join(map(str, s_prime)))

if __name__ == '__main__':
    solve()
