import sys

def move_time(from_comp, to_comp):
    if from_comp == to_comp:
        return 0
    if from_comp == 1 and to_comp == 2:
        return 1
    if from_comp == 1 and to_comp == 3:
        return 2
    if from_comp == 2 and to_comp == 1:
        return 2
    if from_comp == 2 and to_comp == 3:
        return 1
    if from_comp == 3 and to_comp == 1:
        return 1
    if from_comp == 3 and to_comp == 2:
        return 2
    return float('inf')

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    comp = []
    for _ in range(n):
        comp.append(int(next(it)))

    # Build adjacency list for dependencies
    graph = [[] for _ in range(n)]
    for i in range(n):
        k = int(next(it))
        for _ in range(k):
            j = int(next(it)) - 1  # 0-indexed
            graph[i].append(j)

    # Topological sort
    in_degree = [0] * n
    for i in range(n):
        for j in graph[i]:
            in_degree[j] += 1

    queue = [i for i in range(n) if in_degree[i] == 0]
    topo = []
    while queue:
        u = queue.pop(0)
        topo.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[mask][c] = minimum time
    # mask: integer representing completed parts (1 << i means part i+1 completed)
    # c: 0=computer 1, 1=computer 2, 2=computer 3
    INF = float('inf')
    dp = [[INF] * 3 for _ in range(1 << n)]

    # Initial states: start at any computer
    for c in range(3):
