import sys

def solve(board):
    """Find the minimum moves for white and black pawns to reach their goals"""
    min_white = float('inf')
    min_black = float('inf')

    for row in range(8):
        for col in range(8):
            if board[row][col] == 'W':
                # White pawn wants to reach row 0 (row 1 in 1-indexed)
                # It needs row moves to reach row 0
                moves = row
                if moves < min_white:
                    min_white = moves
            elif board[row][col] == 'B':
                # Black pawn wants to reach row 7 (row 8 in 1-indexed)
                # It needs 7 - row moves to reach row 7
                moves = 7 - row
                if moves < min_black:
                    min_black = moves

    # Player A moves first
    # A wins if min_white < min_black (A can reach goal first)
    # B wins otherwise
    if min_white < min_black:
        return 'A'
    else:
        return 'B'

