import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    if n == 1:
        print("0.000000")
        return

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)

    # We need to compute expected value correctly - the order of children doesn't matter
    # because we're averaging

    expected = [0.0] * (n + 1)

    # Stack for DFS: (node, parent, visited)
    stack = [(1, -1, False)]

    while stack:
        node, parent, visited = stack.pop()
        if visited:
            # Calculate expected value after children are processed
            children = [neighbor for neighbor in adj[node] if neighbor != parent]

            if not children:
                expected[node] = 0.0
            else:
                sum_exp = 0.0
                for child in children:
                    sum_exp += expected[child]
                expected[node] = 1.0 + sum_exp / len(children)
        else:
            stack.append((node, parent, True))

            # Push children in reverse order
            for child in reversed(adj[node]):
                if child != parent:
                    stack.append((child, node, False))

    print(f"{expected[1]:.15f}")

if __name__ == "__main__":
