import sys
from collections import defaultdict, deque

def topological_sort(n, adj):
    """Return topological order if graph is a DAG, else return None"""
    indegree = [0] * (n + 1)
    for u in adj:
        for v in adj[u]:
            indegree[v] += 1

    q = deque()
    for i in range(1, n + 1):
        if indegree[i] == 0:
            q.append(i)

    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                q.append(v)

    if len(topo) != n:
        return None  # not a DAG
    return topo

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
