def is_subsequence(s, t):
    """Check if t is a subsequence of s."""
    it = iter(s)
    return all(c in it for c in t)

def solve():
    s = input().strip()
    t = input().strip()

    n = len(s)
    m = len(t)

    if not is_subsequence(s, t):
        print("No")
        return

    # Compute prefix match lengths: prefix[i] is the length of the longest
    # prefix of t that is a subsequence of s[0...i-1]
    prefix = [0] * (n + 1)
    pos = 0
    for i in range(1, n + 1):
        if pos < m and s[i-1] == t[pos]:
            pos += 1
        prefix[i] = pos

    # Compute suffix match lengths: suffix[i] is the length of the longest
    # suffix of t that is a subsequence of s[i...n-1]
    suffix = [0] * (n + 1)
    pos = 0
    for i in range(n - 1, -1, -1):
        if pos < m and s[i] == t[m - 1 - pos]:
            pos += 1
        suffix[i] = pos

    # For each position i, check if there exists a split point
    # where we match t[0...k] in s[0...i-1] and t[k+1...m-1] in s[i...n-1]
    for i in range(n):
        len_before = prefix[i]
        len_after = suffix[i]

        if len_before + len_after >= m:
            if len_before >= m:
                # Already matched all of t, we need to match at least the first part
                # that we matched before i
                found = True
            elif len_after >= m - len_before:
                # We matched first len_before characters before i
                # and last (m - len_before) characters after i
                found = True
            else:
                found = False
        else:
            found = False

        if not found:
            print("No")
            return

    print("Yes")

