def is_subsequence(s, t):
    """Check if t is a subsequence of s."""
    it = iter(s)
    return all(c in it for c in t)

def solve():
    s = input().strip()
    t = input().strip()

    n = len(s)
    m = len(t)

    if not is_subsequence(s, t):
        print("No")
        return

    # Compute prefix: length of prefix of t matched in s[0..i-1]
    prefix = [0] * (n + 1)
    pos = 0
    for i in range(1, n + 1):
        if pos < m and s[i-1] == t[pos]:
            pos += 1
        prefix[i] = pos

    # Compute suffix: length of suffix of t matched in s[i..n-1]
    # Suffix of t is from some position l to the end, i.e., t[l..m-1]
    # We want to know the longest match starting from some character
    suffix = [0] * (n + 1)
    pos = 0
    # Instead of matching from the end, match from the start with t reversed
    for i in range(n - 1, -1, -1):
        if pos < m and s[i] == t[m - 1 - pos]:
            pos += 1
        suffix[i] = pos

    for i in range(n):
        len_prefix = prefix[i]
        len_suffix = suffix[n - i]

        if (len_prefix + len_suffix) >= m:
            if len_prefix >= m:
                found = True
            elif len_suffix >= m - len_prefix:
                found = True
            else:
                found = False
        else:
            found = False

        if not found:
            print("No")
            return

    print("Yes")

