    n, k = map(int, sys.stdin.readline().split())

    if k == 1:
        print('a' * n)
        return

    chars = [chr(ord('a') + i) for i in range(k)]

    # Simple greedy approach
    result = ['a']

    while n > 1:
        # Get the current character
        last = result[-1]

        # Try each character
        for i, c in enumerate(chars):
            # Skip if the same as the last character
            if c == last:
                continue

            # Check if we've already seen this pair
            pair = (last, c)
            found = False
            for j in range(len(result) - 1):
                if result[j] == pair[0] and result[j+1] == pair[1]:
                    found = True
                    break

            if found:
                continue

            result.append(c)
            n -= 1
            break

        else:
            # We can't add any new character, so add 'a'
            result.append('a')
            n -= 1

    if n > 0:
        result.append('a')

    print(''.join(result))

