import sys

def count_loops(n):
    """Count the number of loops in the decimal representation of n."""
    loops = 0
    for ch in str(n):
        if ch == '0':
            loops += 1
        elif ch == '4':
            loops += 1
        elif ch == '6':
            loops += 1
        elif ch == '8':
            loops += 2
        elif ch == '9':
            loops += 1
    return loops

def solve(k):
    """Find a number with exactly k loops."""
    if k == 0:
        return -1

    # If k is even, use k/2 eights
    if k % 2 == 0:
        return '8' * (k // 2)

    # If k is odd, use one 0 (for 1 loop) and (k-1)/2 eights
    return '10' + '8' * ((k - 1) // 2)

if __name__ == '__main__':
    k = int(sys.stdin.readline())
    result = solve(k)
    print(result)
