n = int(input())

# Function to calculate product of digits
def digit_product(num):
    product = 1
    for ch in str(num):
        product *= int(ch)
    return product

# Convert n to string
s = str(n)
max_product = 0

# Try all possibilities
# 1. Keep the number as is
max_product = max(max_product, digit_product(n))

# 2. Try making all digits 9 (but not exceeding n)
# If n has k digits, try numbers with k-1 digits all 9s
if len(s) > 1:
    max_product = max(max_product, digit_product(int('9' * (len(s) - 1))))

# 3. Try replacing digits to maximize product
# 4. Try making digits after position i all 9s
for i in range(len(s)):
    # Try making this digit 9 and all subsequent digits 9
    if i < len(s) - 1:
        candidate_str = s[:i] + '9' + '9' * (len(s) - i - 1)
        if int(candidate_str) <= n:
            max_product = max(max_product, digit_product(int(candidate_str)))

# 5. Try replacing a 9 with 8 and adding a 9
for i in range(len(s)):
    if i < len(s) - 1:
        # If current digit is 9, try making it 8 and next digit 9
        if s[i] == '9':
            candidate_str = s[:i] + '8' + '9' + '9' * (len(s) - i - 2)
            if int(candidate_str) <= n:
