t = int(input())
mod = 10**9 + 7

for _ in range(t):
    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    a.sort(reverse=True)

    # DP table: dp[j][s] = number of ways to choose j elements that sum to s
    dp = [[0] * (sum(a[:k]) + 1) for _ in range(k + 1)]
    dp[0][0] = 1

    for val in a:
        for j in range(k, 0, -1):
            for s in range(sum(a[:k]), val - 1, -1):
                dp[j][s] = (dp[j][s] + dp[j-1][s - val]) % mod

    print(dp[k][sum(a[:k])])
"}

