import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    ages = list(map(int, data[1:1+n]))

    # Coordinate compression
    unique_ages = sorted(set(ages))
    age_to_rank = {v: i+1 for i, v in enumerate(unique_ages)}
    max_rank = len(unique_ages)

    # Segment tree where each node stores the minimum age in its range
    class SegmentTree:
        def __init__(self, size, ages):
            self.n = size
            self.min_tree = [float('inf')] * (2 * self.n)
            for i in range(self.n):
                self.min_tree[self.n + i] = ages[i]
            for i in range(self.n - 1, 0, -1):
                self.min_tree[i] = min(self.min_tree[2*i], self.min_tree[2*i+1])

        def query_max_index(self, target_age, left, right):
            # Find the rightmost index in [left, right] with value < target_age
            # Returns the maximum index found, or -1 if none
            def _query(node, node_left, node_right, query_left, query_right):
                if node_right < query_left or node_left > query_right:
                    return -1
                if node_left >= query_left and node_right <= query_right:
                    # This whole range is within query range
                    if self.min_tree[node] >= target_age:
                        return -1
                    # Find rightmost position in this range
                    if node_left == node_right:
                        return node_left
                    # Check right child first
                    right_result = _query(2*node, node_right - (node_right - node_left + 1) // 2, node_right, query_left, query_right)
                    if right_result != -1:
                        return right_result
                    # Check left child
                    left_result = _query(2*node + 1, node_left, node_right - (node_right - node_left + 1) // 2 - 1, query_left, query_right)
                    return left_result
                mid = (node_left + node_right) // 2
                right_result = _query(2*node, mid+1, node_right, query_left, query_right)
                if right_result != -1:
                    return right_result
                left_result = _query(2*node + 1, node_left, mid, query_left, query_right)
                return left_result
            return _query(1, 0, self.n - 1, left, right)

        def update(self, index, value):
            index += self.n
            self.min_tree[index] = value
            index //= 2
            while index >= 1:
                self.min_tree[index] = min(self.min_tree[2*index], self.min_tree[2*index+1])
                index //= 2

    # Initialize segment tree with all ages set to infinity
    st = SegmentTree(n, [float('inf')] * n)
    result = [-1] * n

    # Iterate from right to left
    for i in range(n-1, -1, -1):
        # Query for the rightmost position j > i with age < ages[i]
        result[i] = st.query_max_index(ages[i], i+1, n-1)
        if result[i] != -1:
