    # We need to find the rightmost position with age < target_age
    class SegmentTree:
        def __init__(self, data):
            self.n = len(data)
            self.size = 1
            while self.size < self.n:
                self.size <<= 1
            self.min_tree = [float('inf')] * (2 * self.size)
