def get_time_before_row(row, k):
    # For group k, rows are: 1+3k, 3+3k, 2+3k, 4+3k
    # They serve 1+3k and 3+3k first (12 seconds), then move (1 second),
    # then serve 2+3k and 4+3k (12 seconds)

    if row == 1 + 3*k:
        # First row in group
        return 0
    elif row == 3 + 3*k:
        # Second row in group (attendant 2 serves)
        return 6  # time to serve first row (1+3k)
    elif row == 2 + 3*k:
        # Third row in group (after move)
        return 6 + 6 + 1  # time to serve first two rows and move
    elif row == 4 + 3*k:
        # Fourth row in group (attendant 2 serves second)
        return 6 + 6 + 1 + 6  # time to serve first three rows and move

# Time for each group of 4 rows
GROUP_TIME = 25  # 12 (first two rows) + 1 (move) + 12 (last two rows)

n, s = input().split()
n = int(n)

# Find which group row n belongs to
if n % 3 == 1:
    k = (n - 1) // 3
    # Row is 1+3k
    time = k * GROUP_TIME
    time += get_time_before_row(n, k)
    pos = 1
elif n % 3 == 2:
    k = (n - 2) // 3
    # Row is 2+3k
    time = k * GROUP_TIME
    time += get_time_before_row(n, k)
    pos = 1
elif n % 3 == 0:
    # Special case: n = 3+3k
    k = (n - 3) // 3
    # Row is 3+3k
    time = k * GROUP_TIME
    time += get_time_before_row(n, k)
    pos = 1
else:
    raise ValueError("Invalid row")

# Calculate position within the row
if s == 'f':
    pos = 1
elif s == 'e':
    pos = 2
elif s == 'd':
    pos = 3
elif s == 'c':
    pos = 4
elif s == 'b':
    pos = 5
elif s == 'a':
    pos = 6
else:
    raise ValueError("Invalid seat")

print(time + pos - 1)
