def count_crosses(n, m, s):
    if s % 2 == 0:
        return 0

    total = 0
    target = s + 1

    # Precompute all possible H = (2a+1)*(2b+1)
    H_map = {}
    max_a = min(n // 2, (n - 1) // 2)
    max_b = min(m // 2, (m - 1) // 2)

    for a in range(max_a + 1):
        for b in range(max_b + 1):
            h = (2 * a + 1) * (2 * b + 1)
            if h not in H_map:
                H_map[h] = 0
            H_map[h] += 1

    # For each cell (x0, y0), count valid crosses
    for x0 in range(1, n + 1):
        for y0 in range(1, m + 1):
            # Horizontal bar limits
            max_h_a = min(x0 - 1, n - x0)
            max_h_b = min(y0 - 1, m - y0)

            # Vertical bar limits
            max_v_a = min(x0 - 1, n - x0)
            max_v_b = min(y0 - 1, m - y0)

            # Count crosses with this center
            count = 0

            # Try all possible horizontal bar sizes
            for a in range(max_h_a + 1):
                for b in range(max_h_b + 1):
                    h = (2 * a + 1) * (2 * b + 1)

                    # Try all possible vertical bar sizes
                    for c in range(max_v_a + 1):
                        for d in range(max_v_b + 1):
                            v = (2 * c + 1) * (2 * d + 1)

                            if h + v == target:
                                count += 1

            total += count

    return total

