def solve():
    import sys
    input = sys.stdin.read().split()
    data = list(map(int, input))
    if not data:
        return

    n = data[0]
    m = data[1]
    q = data[2]

    # rows and columns are 1-indexed
    rows = set()
    cols = set()

    # Build bipartite graph
    # rows and cols are 1-indexed
    parent = {}
    rank = {}

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            if rank[root_u] > rank[root_v]:
                parent[root_v] = root_u
            else:
                parent[root_u] = root_v
                if rank[root_u] == rank[root_v]:
                    rank[root_v] += 1

    for i in range(q):
        r = data[3 + 2*i]
        c = data[4 + 2*i]

