def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    # Read computer assignments
    c = [0] + [int(next(it)) for _ in range(n)]  # 1-indexed

    # Read dependencies
    graph = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        k = int(next(it))
        # Read k values
        values = [int(next(it)) for _ in range(k)]
        for j in values:
            graph[i].append(j)

    # Topological sort
    in_degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v in graph[u]:
            in_degree[v] += 1

    queue = [i for i in range(1, n + 1) if in_degree[i] == 0]
    topo_order = []
    while queue:
        u = queue.pop(0)
        topo_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[c][mask] = minimum time to complete parts in mask and end at computer c
    # Using 1-indexed for computer
    # dp = [dictionary for computer 1 to 3]
    dp = [{} for _ in range(4)]  # dp[0] unused, dp[1], dp[2], dp[3]

    # Start with no parts completed
    for computer in range(1, 4):
        dp[computer][0] = 0

    for u in topo_order:
        # Current part u can be completed on computer c_u
        c_u = c[u]

        # For each possible state
        for computer in range(1, 4):
            for mask, time in dp[computer].items():
                # Option 1: Complete part u now (if not already completed)
                if not (mask & (1 << (u - 1))):
                    new_mask = mask | (1 << (u - 1))
                    new_time = time + 1  # Time to complete part u

                    # We end at computer c_u
                    if new_mask not in dp[c_u] or dp[c_u][new_mask] > new_time:
                        dp[c_u][new_mask] = new_time

                # Option 2: Move to computer c_u and complete part u later
                # We can also just stay and complete if we're already at the right computer
                if computer == c_u:
                    # Just complete it
                    if not (mask & (1 << (u - 1))):
                        new_mask = mask | (1 << (u - 1))
                        new_time = time + 1
                        if new_mask not in dp[computer] or dp[computer][new_mask] > new_time:
                            dp[computer][new_mask] = new_time

    # Find the minimum time to complete all parts
    full_mask = (1 << n) - 1
    min_time = float('inf')
    for computer in range(1, 4):
        min_time = min(min_time, dp[computer].get(full_mask, float('inf')))

    print(min_time)

