def find_cycle_lengths(crush):
    n = len(crush)
    visited = [False] * n
    cycle_lengths = []

    for i in range(n):
        if not visited[i]:
            current = i
            path = []
            while True:
                if visited[current]:
                    # Check if we've returned to the start of the cycle
                    if current == path[0]:
                        cycle_lengths.append(len(path))
                    break
                visited[current] = True
                path.append(current)
                current = crush[current] - 1  # Convert to 0-indexed

    return cycle_lengths

def lcm(a, b):
    return a * b // math.gcd(a, b)

def solve():
    n = int(input())
    crush = list(map(int, input().split()))

    cycle_lengths = find_cycle_lengths(crush)

    if not cycle_lengths:
        print(-1)
        return

    # Find the smallest t such that 2t % L == 0 for all L
    # LCM of all L/2 where L is even, and L where L is odd
    result = 1
    for L in cycle_lengths:
        if L % 2 == 0:
            # L is even, need L/2 divides t
            # L = 2^k * m, need 2^{k-1} * m divides t
            # LCM with result
            power_of_2 = L
            while power_of_2 % 2 == 0:
                power_of_2 //= 2
            # power_of_2 is L/2
            result = lcm(result, power_of_2)
        else:
            # L is odd, need L divides t
            result = lcm(result, L)

    print(result)

