                    return i
            return n  # position n is out of bounds

        # Place each filling
        for filling, count in sorted_fillings:
            positions_list = []

            # First, place the first occurrence
            if count > 1:
                pos = 0
                if not used[pos]:
                    used[pos] = True
                    positions[pos] = filling
                    positions_list.append(pos)
                else:
                    pos = find_next_position(0)
                    positions[pos] = filling
                    positions_list.append(pos)

            # Then, place the remaining occurrences spaced out
            if count > 1:
                n_positions = n - count + 1
                space = n_positions // (count - 1)

                for i in range(1, count):
                    offset = i * space
                    target_pos = positions_list[0] + offset + 1  # +1 to space out
                    if target_pos >= n:
                        # Not enough space, just place at next available position
                        pos = find_next_position(n-1)
                        if pos == n:
                            # No position available, but should never happen
                            continue
                        positions[pos] = filling
                        positions_list.append(pos)
                    else:
                        # Make sure the target position is available
                        while used[target_pos] and target_pos < n:
                            target_pos += 1
                        if not used[target_pos]:
                            used[target_pos] = True
                            positions[target_pos] = filling
                            positions_list.append(target_pos)
                        else:
                            # Could not find a valid position
                            pos = find_next_position(n-1)
                            positions[pos] = filling
                            positions_list.append(pos)

        min_dist = float('inf')
        for filling in freq:
            indices = [i for i, val in enumerate(positions) if val == filling]
            if len(indices) >= 2:
                for i in range(1, len(indices)):
                    dist = indices[i] - indices[i-1] - 1
                    min_dist = min(min_dist, dist)

        results.append(str(min_dist))

    sys.stdout.write("\n".join(results))

