    # Check if we can uniquely determine N with k modes
    def can_determine_with_k_modes(k):
        # Try all combinations of k modes
        from itertools import combinations
        for modes in combinations(range(n), k):
            # For each mode, find the range of N that it covers
            lower = 0
            upper = 0
            for i in modes:
                ai = a[i]
                # Try all possible values of bi for this mode
                # Bi ranges from 1 to max_pages
                max_pages = (x + ai - 1) // ai
