    # Actually, if the number itself has a 0, the maximum product might not be the number itself
    # For 10, the maximum product is 9, not 10 (which is 1*0=0)

    for ch in s:
        max_product *= int(ch)

    # This is a special case: if there's a zero in the digits, we should
    # check the scenario where we have just the number without the 0? But that's not straightforward.

    # Try reducing each digit and filling with 9s
    for i in range(len(s)):
        if s[i] == '0':
            continue

        if i == 0:
            # First digit: we only consider reducing to 1 (since reducing to 0 introduces a 0 in the product)
            if s[i] == '1':
                # Reducing 1 to 0 gives product 0, not better
                continue
            else:
                # Reduce by 1 (at least 2, can reduce to 1, which doesn't give a 0)
                reduced_digit = str(int(s[i]) - 1)
                candidate = reduced_digit + '9' * (len(s) - 1)
        else:
            # Later digits: we can reduce to 0 (which gives a 0 in the product, but we'll compare anyway)
            reduced_digit = str(int(s[i]) - 1)
            if s[i] == '1':
                # 1-1=0 gives product 0, not worth considering
                continue
            else:
                if i < len(s) - 1:
                    # If we have remaining digits, they should be 9s
                    candidate = s[:i] + reduced_digit + '9' * (len(s) - i - 1)
                else:
                    # If we are at the last digit, just the reduced digit
                    candidate = s[:i] + reduced_digit

        # Compute product
        product = 1
        for ch in candidate:
            if ch == '0':
                product = 0
                break
            product *= int(ch)

        if product > max_product:
            max_product = product

    # Special case: what about numbers that are not adjacent to a zero? For example, 999999999
    # That's already covered by the all 9s check

    # Also, what about a number like 999999998? That should be covered by the loop

    return max_product

