import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    crush = list(map(int, data[1:n+1]))

    # Build graph
    graph = [[] for _ in range(n)]
    for i in range(n):
        graph[i].append(crush[i] - 1)  # 0-indexed

    # Find cycles
    visited = [False] * n
    cycles = []

    for i in range(n):
        if not visited[i]:
            # Start a new cycle
            current = i
            cycle = []
            while True:
                if visited[current]:
                    if current in cycle:
                        # Found a cycle
                        idx = cycle.index(current)
                        cycle = cycle[idx:] + cycle[:idx]
                        cycles.append(cycle)
                    break
                visited[current] = True
                cycle.append(current)
                current = crush[current] - 1

    # Check if the graph is strongly connected
    # For each node, check if we can reach all other nodes
    for start in range(n):
        visited = [False] * n
        queue = [start]
        visited[start] = True
        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        if not all(visited):
            print(-1)
            return

    # Find the smallest t
    result = 1
    for cycle in cycles:
        L = len(cycle)
        if L % 2 == 1:
            # Odd cycle, t = L
            result = max(result, L)
        else:
            # Even cycle, t = L/2
            result = max(result, L // 2)

    print(result)

if __name__ == "__main__":
    solve()
