def can_reach_goal(board, r, c, goal_row, is_white):
    """Check if a pawn at (r, c) can reach goal_row"""
    steps = abs(r - goal_row)

    # Check if the path is clear
    for i in range(steps):
        if is_white:
            # White pawn moves up, target row is smaller
            if board[r - i - 1][c] != '.':
                return False
        else:
            # Black pawn moves down, target row is larger
            if board[r + i + 1][c] != '.':
                return False

    return True

def min_steps_to_goal(board, goal_row, is_white):
    """Find minimum steps for any pawn to reach goal_row"""
    min_steps = float('inf')
    for r in range(8):
