import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)

    # For each character, find the maximum gap between consecutive occurrences
    # The minimum k for that character to be dominant is max_gap + 1

    min_k = n + 1  # Initialize with a value greater than n

    # For each character in the alphabet
    for c in set(s):
        positions = []
        for i, char in enumerate(s):
            if char == c:
                positions.append(i)

        # Calculate gaps
        gaps = []
        prev = -1
        for pos in positions:
            if prev == -1:
                gaps.append(pos)  # From start to first occurrence
            else:
                gaps.append(pos - prev - 1)  # Between two consecutive occurrences
            prev = pos
        if prev == -1:
            # Character not found, skip
            continue
        gaps.append(n - prev - 1)  # From last occurrence to end

        max_gap = max(gaps)
        k = max_gap + 1

        if k < min_k:
            min_k = k

    print(min_k)

if __name__ == "__main__":
    solve()
"}

