    # Find valid range for x
    lower = max(0, *[ -s[i] for i in range(1, n + 1) ])
    upper = min(w, *[ w - s[i] for i in range(1, n + 1) ])

    if lower > upper:
        print(0)
    else:
        print(upper - lower + 1)

