def factorize(n):
    factors = []
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

n, k = map(int, input().split())
factors = factorize(n)

if len(factors) < k:
    print(-1)
else:
    # Take the first (k-1) factors as they are
    # The last factor is the product of the remaining factors
    result = factors[:k-1] + [1]
    remaining = factors[k-1:]
    result[-1] = 1
    for factor in remaining:
        result[-1] *= factor
    print(' '.join(map(str, result)))
"}

